    await addProductToCart(page);
    await expect(page.locator("#email-preview-panel .preview-to")).toHaveText("someone@example.com");
    await fillCheckoutEmail(page, "buyer.qa@skyramp.dev");
    await expect(page.locator("#email-preview-panel .preview-to")).toHaveText("buyer.qa@skyramp.dev");
    await expect(page.locator("#email")).toHaveValue("buyer.qa@skyramp.dev");
    await expect(page.locator("#email-preview-panel .preview-address")).toHaveText("1600 Amphitheatre Parkway, Mountain View, CA, 94043, United States");
